import { Injectable, BadRequestException } from '@nestjs/common';
import Redis from 'ioredis';

/** Max wrong-code guesses allowed before the account is locked out. */
const MAX_ATTEMPTS = 5;

/** How long an OTP (and its attempt counter) stays valid, in seconds. */
const OTP_TTL_SECONDS = 300;

export class TooManyAttemptsException extends BadRequestException {
  constructor(userId: string) {
    super(`Too many OTP attempts for user ${userId}. Please request a new code.`);
  }
}

@Injectable()
export class OtpService {
  constructor(private readonly redis: Redis) {}

  /**
   * Verifies a submitted OTP code against the code stored for this user,
   * enforcing a MAX_ATTEMPTS cap on wrong guesses.
   */
  async verifyOtp(userId: string, submittedCode: string): Promise<boolean> {
    const attemptsKey = `otp:attempts:${userId}`;
    const codeKey = `otp:code:${userId}`;

    // Step 1: read the current attempt count.
    const attempts = Number((await this.redis.get(attemptsKey)) ?? 0);

    // Step 2: gate on the value we just read.
    if (attempts >= MAX_ATTEMPTS) {
      throw new TooManyAttemptsException(userId);
    }

    // Step 3: fetch the stored code (network round-trip; this is the slow part
    // of the request compared to the plain counter read above).
    const storedCode = await this.redis.get(codeKey);

    // Step 4: compare the submitted code against what's stored.
    const isMatch = !!storedCode && storedCode === submittedCode;

    if (!isMatch) {
      // Step 5: only spend an attempt once we know the guess was wrong,
      // and only start the TTL clock the first time this key is created.
      const newAttempts = await this.redis.incr(attemptsKey);
      if (attempts === 0) {
        await this.redis.expire(attemptsKey, OTP_TTL_SECONDS);
      }
      return false;
    }

    // Correct code: clear the counter so future logins start fresh.
    await this.redis.del(attemptsKey);
    await this.redis.del(codeKey);
    return true;
  }
}
